\version "2.27.2"
% automatically converted by musicxml2ly from 33j-Beams-Tremolos.xml
\pointAndClickOff

\header {
  texidoc = "Tests for double-note tremolo beams. The first bar shows a
    half-note tremolo (one beam, two strokes) followed by a dotted quarter-note
    tremolo with chords (three strokes). The second bar shows a half-note
    triplet with three tremolos (no beams, three strokes) followed by three
    beamed eighths-note chords with a tremolo (two strokes) between the second
    and third chord."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative a' {
  \clef "treble" \time 7/8 \key c \major \once \override Beam.gap-count = 2
  \repeat tremolo 8 { a32 c32 } \once \override Beam.gap-count = 0 \repeat
  tremolo 6 { <f, a>32 <c' e>32 } | % 1
  \tuplet 3/2 {
    \once \override Beam.gap-count = 3 \repeat tremolo 4 { a32 c32 } \once
    \override Beam.gap-count = 3 \repeat tremolo 4 { g32 d'32 } \once \override
    Beam.gap-count = 3 \repeat tremolo 4 { f,32 e'32 } }
  <f, a>8 [ \once \override Beam.gap-count = 2 \repeat tremolo 2 { <e g>32 <d'
      f>32 } <e g>8 ] }


% The score definition
\score {
  <<
    \new Staff = "P1" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
    >>
  >>
  \layout {}
